// GENERATED BY SYMPLRV3 — DO NOT EDIT
// Typed error model — one shape the whole app can switch on.
export type ErrorKind = 'network' | 'auth' | 'validation' | 'notFound' | 'server' | 'unknown';

export class AppError extends Error {
  kind: ErrorKind;
  status?: number;
  cause?: unknown;
  /** The API's OWN words, when the response body carried a message. Kept
   * separate from `message` so `errorMessage` can prefer it over this
   * layer's generic per-kind copy without having to guess which it is. */
  apiMessage?: string;
  constructor(
    kind: ErrorKind,
    message: string,
    opts: { status?: number; cause?: unknown; apiMessage?: string } = {},
  ) {
    super(message);
    this.name = 'AppError';
    this.kind = kind;
    this.status = opts.status;
    this.cause = opts.cause;
    this.apiMessage = opts.apiMessage;
  }
}

export type Result<T> = { ok: true; value: T } | { ok: false; error: AppError };

/** Keys real APIs put a human-readable failure message under, best first. */
const MESSAGE_KEYS = [
  'message',
  'error_description',
  'errorMessage',
  'error_message',
  'detail',
  'details',
  'title',
  'description',
  'reason',
  'error',
];
/** Nested envelopes worth descending into ({ error: {...} }, { errors: [...] }). */
const MESSAGE_NESTS = ['error', 'errors', 'data', 'fault', 'response', 'result'];

/**
 * Dig a human message out of an arbitrary error/response body.
 *
 * A 400 tells the user nothing useful as "Invalid request" — the reason is in
 * the body ("Incorrect username or password.", "Amount exceeds daily limit").
 * Shapes vary per service, so probe the keys they actually use rather than
 * assuming one envelope.
 */
/** A JSON-looking string body is parsed once, then read as an object. */
function messageFromString(value: string, depth: number): string | undefined {
  const s = value.trim();
  if (!s) return undefined;
  if (depth === 0 && /^[[{]/.test(s)) {
    try {
      return pickMessage(JSON.parse(s), 1);
    } catch {
      return s.slice(0, 300);
    }
  }
  return s.slice(0, 300);
}

/** First message found anywhere in an array body. */
function messageFromArray(value: unknown[], depth: number): string | undefined {
  for (const item of value) {
    const hit = pickMessage(item, depth + 1);
    if (hit) return hit;
  }
  return undefined;
}

/**
 * The reason an API gave, dug out of whatever shape it used. Split by body KIND
 * (string / array / object) — as one function this was 25 cognitive complexity
 * (Sonar S3776).
 */
export function pickMessage(value: unknown, depth = 0): string | undefined {
  if (typeof value === 'string') return messageFromString(value, depth);
  if (!value || typeof value !== 'object' || depth > 4) return undefined;
  if (Array.isArray(value)) return messageFromArray(value, depth);
  const rec = value as Record<string, unknown>;
  for (const key of MESSAGE_KEYS) {
    const v = rec[key];
    if (typeof v === 'string' && v.trim()) return v.trim().slice(0, 300);
  }
  for (const key of MESSAGE_NESTS) {
    if (!(key in rec)) continue;
    const hit = pickMessage(rec[key], depth + 1);
    if (hit) return hit;
  }
  return undefined;
}

/** Normalize any thrown value (fetch error, ApiError, …) to an AppError. */
export function toAppError(e: unknown): AppError {
  if (e instanceof AppError) return e;
  const status = (e as { status?: number })?.status;
  // ApiError carries the raw response body; that is where the reason lives
  const apiMessage = pickMessage((e as { body?: unknown })?.body);
  const opts = { status, cause: e, apiMessage };
  if (status === 401 || status === 403) return new AppError('auth', 'Not authorized', opts);
  if (status === 404) return new AppError('notFound', 'Not found', opts);
  if (status && status >= 500) return new AppError('server', 'Server error', opts);
  if (status && status >= 400) return new AppError('validation', 'Invalid request', opts);
  const msg = e instanceof Error ? e.message : String(e);
  return new AppError(/network|fetch/i.test(msg) ? 'network' : 'unknown', msg, opts);
}

/** User-facing copy: the API's own reason when it gave one, else per-kind. */
/**
 * Start a promise nobody awaits, without losing its rejection.
 *
 * These were emitted as `void somePromise()` — the operator says "deliberately
 * not awaited", but it also drops the rejection on the floor, so a failed
 * analytics call or storage write surfaced only as an unhandled-rejection
 * warning with no context. Sonar reports the operator (S3735); the reason to
 * replace it is that a swallowed error should at least say where it came from.
 */
export function fireAndForget(p: Promise<unknown> | undefined | null, label?: string): void {
  Promise.resolve(p).catch((e: unknown) => {
    console.warn('[gen] background task failed' + (label ? ` (${label})` : ''), e);
  });
}

/** The envelope every SDK integration action resolves to. */
export type SdkResult = { ok: boolean; data?: unknown };

/**
 * Run an SDK integration action so EVERY failure mode degrades the same way a
 * missing module does: one settled { ok: false } envelope.
 *
 * The old caller, `(mod()?.action() ?? Promise.resolve({ ok: false }))`,
 * only degraded the null-module case. A loaded module whose native side is
 * absent fails LOUDER: in Expo Go react-native-nfc-manager's JS imports fine
 * on Android and then every call throws Hermes's "Cannot convert null value
 * to object" (property access on the null NativeModule), and a Nitro-based
 * SDK throws its own install error — synchronously, or as a rejection. All of
 * it lands here as { ok: false, data: e }; the raw error goes to the console
 * for the developer, and response rules can still read `data`.
 *
 * `missingModule` names the SDK's npm package. The run() expression is the
 * optional-chained `mod()?.action(args)` — it settles NULLISH exactly when
 * the memoized module-scope require came back null (the SDK's JS never loaded
 * in this runtime; Expo Go). That is a DIFFERENT failure from a present
 * module whose action threw: the marker envelope lets the toast layer say
 * "needs a real device build" instead of the generic line. Rules are
 * unaffected — the envelope is still { ok: false }, status still 0.
 */
export function safeInvoke(
  run: () => Promise<SdkResult> | SdkResult | undefined | null,
  missingModule?: string,
): Promise<SdkResult> {
  const absent = (): SdkResult => {
    if (!missingModule) return { ok: false };
    console.warn('[gen] SDK module missing from this runtime (Expo Go?):', missingModule);
    return { ok: false, data: { missingNativeModule: missingModule } };
  };
  let raw: Promise<SdkResult> | SdkResult | undefined | null;
  try {
    raw = run();
  } catch (e) {
    console.warn('[gen] SDK action threw', e);
    return Promise.resolve({ ok: false, data: e });
  }
  return Promise.resolve(raw).then(
    (r) => r ?? absent(),
    (e: unknown) => {
      console.warn('[gen] SDK action rejected', e);
      return { ok: false, data: e };
    },
  );
}

export function errorMessage(e: unknown): string {
  const err = toAppError(e);
  // A network failure is about the DEVICE, not the response — our copy is the
  // more useful one there even if something parsed out of a body.
  if (err.apiMessage && err.kind !== 'network') return err.apiMessage;
  switch (err.kind) {
    case 'network':
      return 'No connection. Check your network and try again.';
    case 'auth':
      return 'Your session has expired. Please sign in again.';
    case 'notFound':
      return "That wasn't found.";
    case 'server':
      return 'Something went wrong on our side. Try again shortly.';
    case 'validation':
      return err.message || 'Please check your input.';
    default:
      return err.message || 'Something went wrong.';
  }
}

/** Same, for a plain response BODY (an SDK result envelope, not a throw). */
export function responseMessage(body: unknown): string {
  // safeInvoke's missing-module marker: the SDK's JS never loaded in this
  // runtime (Expo Go has no native binaries), which is an ENVIRONMENT fact,
  // not a bug — say so instead of the generic line. The package name stays in
  // the console; the user never sees internals.
  const missing = (body as { missingNativeModule?: unknown } | null | undefined)
    ?.missingNativeModule;
  if (typeof missing === 'string' && missing) {
    console.warn('[gen] SDK unavailable in this runtime:', missing);
    return "This feature needs a real device build — it can't run inside Expo Go.";
  }
  // A caught exception in `data` is an internal failure, not API copy. Its
  // message is engine-speak — "Cannot convert null value to object" is what
  // Hermes says when a missing native module is called — so the user gets the
  // generic line and the console keeps the real one.
  if (
    body instanceof Error ||
    (body !== null &&
      typeof body === 'object' &&
      typeof (body as { stack?: unknown }).stack === 'string' &&
      typeof (body as { message?: unknown }).message === 'string')
  ) {
    console.warn('[gen] SDK failure detail', body);
    return 'Something went wrong. Please try again.';
  }
  return pickMessage(body) ?? 'Something went wrong. Please try again.';
}
